// 2. Validate Input
// Confirms the standardized alarm from WF-02 has everything the AI prompt needs.

const REQUIRED = ['correlationId', 'vendor', 'alarmType', 'severity', 'nodeName', 'siteId', 'region', 'timestamp'];

const item = $input.first().json;
const missing = REQUIRED.filter((f) => item[f] === undefined || item[f] === null || item[f] === '');

return [{
  json: {
    isValid: missing.length === 0,
    missingFields: missing,
    ...item
  }
}];

// 3. Build Claude Prompt
// Assembles the system prompt (role + rules + output contract) and the
// user prompt (the actual alarm data) that will be sent to Claude.

const item = $input.first().json;

const alarm = {
  correlationId: item.correlationId,
  vendor: item.vendor,
  alarmType: item.alarmType,
  alarmDescription: item.description || item.alarmName || item.alarmType,
  severity: item.severity,
  nodeName: item.nodeName,
  siteId: item.siteId,
  region: item.region,
  timestamp: item.timestamp
};

const systemPrompt = `You are a Senior Telecom NOC (Network Operations Center) Analyst AI for a fiber network operator.

Your job: analyze ONE normalized fiber network alarm and produce an operational assessment for the NOC and field teams.

You MUST follow these business rules when they apply (do not contradict them):
- alarmType FIBER_CUT -> priority Critical, team Transmission, fieldEngineer true
- alarmType LOS -> priority Major, team NOC
- alarmType HIGH_BER -> priority Minor, team "Transmission Monitoring"
- alarmType POWER_FAILURE -> priority Critical, team Power
- alarmType MUX_FAILURE -> priority Critical, team Transmission
For any other alarmType, use your own professional judgment based on telecom fiber network operations best practice.

Output contract (STRICT):
- Return ONLY a single valid JSON object. No markdown, no code fences, no commentary, no explanation before or after.
- The JSON object MUST contain exactly these fields:
  {
    "alarmCategory": string,
    "rootCause": string,
    "impact": string,
    "priority": "Critical" | "Major" | "Minor" | "Warning",
    "recommendedAction": string,
    "estimatedResolution": string,
    "confidence": number between 0 and 1,
    "fieldEngineer": boolean,
    "customerImpact": "High" | "Medium" | "Low",
    "team": string,
    "prevention": string
  }
- "confidence" reflects how certain you are of this specific assessment given the information available, not a fixed number.
- Keep each string field concise: 1-3 sentences, operational and specific, no generic filler.`;

const userPrompt = `Analyze this normalized fiber network alarm and return the JSON object described in your instructions.

Alarm JSON:
${JSON.stringify(alarm, null, 2)}

Remember: respond with ONLY the JSON object, nothing else.`;

return [{
  json: {
    ...item,
    systemPrompt,
    userPrompt
  }
}];

// 5. Parse & Validate AI Output
// Extracts Claude's text response, strips any markdown fencing, parses it as
// JSON, and checks it matches the required schema before trusting it.
//
// Anthropic's Messages API can return a top-level API error instead of a
// normal message (e.g. { type: 'error', error: { type, message } } for
// billing/rate-limit/auth problems) even when the HTTP node's neverError
// option keeps this from throwing. That error object has no 'content'
// array, so treating it as a normal response silently produced a
// misleading 'Unexpected end of JSON input' parseError. This is checked
// for explicitly now so the real Anthropic error message (e.g. 'Your
// credit balance is too low...') surfaces directly instead.

const original = $('3. Build Claude Prompt').first().json;
const response = $input.first().json;

if (response && response.type === 'error') {
  const apiErrorMessage = (response.error && response.error.message) || 'Unknown Anthropic API error';
  return [{
    json: {
      correlationId: original.correlationId,
      vendor: original.vendor,
      alarmType: original.alarmType,
      originalSeverity: original.severity,
      nodeName: original.nodeName,
      siteId: original.siteId,
      region: original.region,
      timestamp: original.timestamp,
      isValid: false,
      parseError: 'Anthropic API error: ' + apiErrorMessage,
      schemaErrors: [],
      rawAiText: '',
      aiOutput: null
    }
  }];
}

let rawText = '';
try {
  const blocks = response.content || [];
  const textBlock = blocks.find((b) => b.type === 'text');
  rawText = textBlock ? textBlock.text : '';
} catch (e) {
  rawText = '';
}

let cleaned = (rawText || '').trim();
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();

let parsed = null;
let parseError = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

const REQUIRED_AI_FIELDS = ['alarmCategory', 'rootCause', 'impact', 'priority', 'recommendedAction', 'estimatedResolution', 'confidence', 'fieldEngineer', 'customerImpact', 'team', 'prevention'];
const schemaErrors = [];

if (parsed) {
  for (const f of REQUIRED_AI_FIELDS) {
    if (parsed[f] === undefined || parsed[f] === null) schemaErrors.push(`Missing field: ${f}`);
  }
  if (parsed.confidence !== undefined && (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1)) {
    schemaErrors.push('confidence must be a number between 0 and 1');
  }
  if (parsed.fieldEngineer !== undefined && typeof parsed.fieldEngineer !== 'boolean') {
    schemaErrors.push('fieldEngineer must be a boolean');
  }
}

const isValid = !!parsed && parseError === null && schemaErrors.length === 0;

return [{
  json: {
    correlationId: original.correlationId,
    vendor: original.vendor,
    alarmType: original.alarmType,
    originalSeverity: original.severity,
    nodeName: original.nodeName,
    siteId: original.siteId,
    region: original.region,
    timestamp: original.timestamp,
    isValid,
    parseError,
    schemaErrors,
    rawAiText: rawText,
    aiOutput: parsed
  }
}];

// 6. Apply Business Rules
// Deterministic safety net: for the 5 alarm types with defined business
// rules, priority/team (and fieldEngineer for Fiber Cut) are ENFORCED
// regardless of what the AI proposed. All other AI fields are kept as-is.
// For alarm types with no defined rule, the AI's judgment is used untouched.

const item = $input.first().json;
const ai = item.aiOutput;

const BUSINESS_RULES = {
  FIBER_CUT: { priority: 'Critical', team: 'Transmission', fieldEngineer: true },
  LOS: { priority: 'Major', team: 'NOC', fieldEngineer: null },
  HIGH_BER: { priority: 'Minor', team: 'Transmission Monitoring', fieldEngineer: null },
  POWER_FAILURE: { priority: 'Critical', team: 'Power', fieldEngineer: null },
  MUX_FAILURE: { priority: 'Critical', team: 'Transmission', fieldEngineer: null }
};

const rule = BUSINESS_RULES[item.alarmType];
const finalOutput = { ...ai };
let businessRuleApplied = false;

if (rule) {
  businessRuleApplied = true;
  finalOutput.priority = rule.priority;
  finalOutput.team = rule.team;
  if (rule.fieldEngineer !== null) {
    finalOutput.fieldEngineer = rule.fieldEngineer;
  }
}

return [{
  json: {
    correlationId: item.correlationId,
    vendor: item.vendor,
    alarmType: item.alarmType,
    originalSeverity: item.originalSeverity,
    nodeName: item.nodeName,
    siteId: item.siteId,
    region: item.region,
    timestamp: item.timestamp,
    businessRuleApplied,
    ...finalOutput
  }
}];

// 7. Compute Confidence Routing
// Confidence > 0.90 -> auto-approved
// Confidence 0.70-0.90 -> manual-review
// Confidence < 0.70 -> human-validation-required

const item = $input.first().json;
const confidence = typeof item.confidence === 'number' ? item.confidence : 0;

let reviewStatus;
if (confidence > 0.9) {
  reviewStatus = 'auto-approved';
} else if (confidence >= 0.7) {
  reviewStatus = 'manual-review';
} else {
  reviewStatus = 'human-validation-required';
}

return [{
  json: {
    ...item,
    reviewStatus,
    aiModel: 'claude-sonnet-5',
    processedAt: new Date().toISOString()
  }
}];
